SELECT ?s ?class ?label ?ts WHERE {
  ?s ?p ?o .
  FILTER (regex(str(?s), "Perimeter_mid_ZN_3|DataCenter_top_ZN_6"))
  ?s rdf:type ?class .
  ?s rdfs:label ?label .
  OPTIONAL { ?s ref:hasTimeseriesId ?ts }
} LIMIT 100

