import csv

cat = {}
with open(CATALOG_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        cat[row['timeseries_id']] = row

# The external refs (tsref UUIDs) for the two occupancy sensors:
# Perimeter_mid_ZN_3: 0361d2c1-48db-57ae-b48b-913d1c1cef38
# DataCenter_top_ZN_6: b3f73bc4-684f-5295-a07e-c26b2b13702c

target_ts = {}
# Try to match by point_uri containing the zone id or by some id in catalog
for ts_id, row in cat.items():
    if 'Occupancy' in row['point_class'] or 'occupancy' in row['point_class'].lower():
        print(ts_id, row['point_uri'], row['point_class'])

import csv

zones = {
    "Perimeter_mid_ZN_3": "0361d2c1-48db-57ae-b48b-913d1c1cef38",
    "DataCenter_top_ZN_6": "b3f73bc4-684f-5295-a07e-c26b2b13702c",
}

vals = {}
with open(VALUES_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        ts = row['timeseries_id']
        if ts in zones.values():
            t = row['timestamp']
            if t.startswith("2018-10-11"):
                hr = int(t[11:13])
                if 8 <= hr <= 18:
                    vals.setdefault(ts, []).append((t, float(row['value'])))

for name, tid in zones.items():
    arr = sorted(vals.get(tid, []))
    print(name, len(arr), arr[:3], arr[-3:] if len(arr)>3 else '')
    mean = sum(v for _,v in arr)/len(arr) if arr else None
    print("  mean =", mean)

mp = sum(v for _,v in vals[zones["Perimeter_mid_ZN_3"]])/len(vals[zones["Perimeter_mid_ZN_3"]])
md = sum(v for _,v in vals[zones["DataCenter_top_ZN_6"]])/len(vals[zones["DataCenter_top_ZN_6"]])
print("diff =", mp - md)
